func firstPersonArmVisualAsset(_ layer: FirstPersonArmLayer) -> FirstPersonArmVisualAsset? {
    firstPersonArmAssets[layer]
}

func firstPersonArmVisualImage(_ layer: FirstPersonArmLayer) -> RGBAImage? {
    guard let asset = firstPersonArmVisualAsset(layer),
          let data = Data(base64Encoded: asset.pngBase64, options: .ignoreUnknownCharacters),
          data.count <= 256 * 1024,
          let image = decodePNG(data),
          image.width == asset.width, image.height == asset.height,
          image.pixels.count == asset.width * asset.height * 4 else { return nil }
    return image
}
